"""
Inventory Management System
Auto-generated by NEXUS Coder AI
"""

import json
import uuid
from datetime import datetime
from pathlib import Path

DB_FILE = Path("inventory.json")


def _load() -> dict:
    if not DB_FILE.exists():
        return {"products": {}, "movements": [], "categories": {}}
    with open(DB_FILE) as f:
        return json.load(f)


def _save(db: dict) -> None:
    tmp = DB_FILE.with_suffix(".tmp")
    with open(tmp, "w") as f:
        json.dump(db, f, indent=2)
    tmp.replace(DB_FILE)


def add_product(name: str, sku: str, price: float,
                qty: int = 0, category: str = "General") -> dict:
    """Add a new product to inventory."""
    db = _load()
    if sku in db["products"]:
        raise ValueError(f"SKU already exists: {sku}")
    product = {
        "id":          str(uuid.uuid4())[:8],
        "sku":         sku,
        "name":        name,
        "category":    category,
        "unit_price":  round(price, 2),
        "stock_qty":   qty,
        "min_stock":   5,
        "is_active":   True,
        "created_at":  datetime.utcnow().isoformat(),
    }
    db["products"][sku] = product
    if qty > 0:
        _record_movement(db, sku, "IN", qty, "Initial stock")
    _save(db)
    return product


def get_product(sku: str) -> dict | None:
    """Retrieve a product by SKU."""
    return _load()["products"].get(sku)


def list_products(category: str = "") -> list:
    """List all active products, optionally filtered by category."""
    db   = _load()
    prods = [p for p in db["products"].values() if p["is_active"]]
    if category:
        prods = [p for p in prods if p["category"] == category]
    return sorted(prods, key=lambda p: p["name"])


def adjust_stock(sku: str, qty: int, movement_type: str = "ADJUST",
                 notes: str = "") -> dict:
    """Adjust stock quantity. movement_type: IN, OUT, ADJUST."""
    db = _load()
    if sku not in db["products"]:
        raise ValueError(f"Product not found: {sku}")
    product = db["products"][sku]
    if movement_type == "OUT" and product["stock_qty"] < qty:
        raise ValueError(f"Insufficient stock. Available: {product['stock_qty']}")
    if movement_type == "IN":
        product["stock_qty"] += qty
    elif movement_type == "OUT":
        product["stock_qty"] -= qty
    else:
        product["stock_qty"] = qty
    _record_movement(db, sku, movement_type, qty, notes)
    _save(db)
    return product


def _record_movement(db: dict, sku: str, mtype: str, qty: int, notes: str):
    db["movements"].append({
        "sku":        sku,
        "type":       mtype,
        "quantity":   qty,
        "notes":      notes,
        "timestamp":  datetime.utcnow().isoformat(),
    })


def low_stock_alerts() -> list:
    """Return products below minimum stock level."""
    return [p for p in _load()["products"].values()
            if p["is_active"] and p["stock_qty"] <= p["min_stock"]]


def get_inventory_value() -> dict:
    """Calculate total inventory value."""
    db      = _load()
    total   = sum(p["stock_qty"] * p["unit_price"]
                  for p in db["products"].values() if p["is_active"])
    return {
        "total_value":    round(total, 2),
        "total_products": len(db["products"]),
        "total_movements": len(db["movements"]),
        "low_stock_count": len(low_stock_alerts()),
    }


def run_repl():
    """Interactive inventory management CLI."""
    print("=" * 55)
    print("  NEXUS Inventory Manager")
    print("  Commands: add, list, stock, value, alerts, exit")
    print("=" * 55)
    while True:
        try:
            cmd = input("inv> ").strip().lower()
            if cmd == "exit":
                break
            elif cmd == "add":
                name     = input("  Name  : ")
                sku      = input("  SKU   : ")
                price    = float(input("  Price : "))
                qty      = int(input("  Qty   : ") or 0)
                product  = add_product(name, sku, price, qty)
                print(f"  Added: [{product['sku']}] {product['name']}")
            elif cmd == "list":
                for p in list_products():
                    print(f"  {p['sku']:<12} {p['name']:<25} Qty:{p['stock_qty']} £{p['unit_price']}")
            elif cmd == "stock":
                sku  = input("  SKU  : ")
                qty  = int(input("  Qty  : "))
                mtype = input("  Type [IN/OUT/ADJUST]: ").upper()
                p    = adjust_stock(sku, qty, mtype)
                print(f"  Updated: {p['name']} → {p['stock_qty']} units")
            elif cmd == "value":
                v = get_inventory_value()
                print(f"  Total Value  : £{v['total_value']}")
                print(f"  Products     : {v['total_products']}")
                print(f"  Low Stock    : {v['low_stock_count']}")
            elif cmd == "alerts":
                for p in low_stock_alerts():
                    print(f"  ⚠ {p['sku']} — {p['name']} — {p['stock_qty']} units left")
            else:
                print("  Unknown command.")
        except (KeyboardInterrupt, EOFError):
            break
        except Exception as e:
            print(f"  Error: {e}")


if __name__ == "__main__":
    run_repl()

