def multiply(a, b):
    """Return the product of a and b."""
    return Decimal(str(a)) * Decimal(str(b))


def divide(a, b):
    """Return the quotient of a and b. Raises ValueError on division by zero."""
    if Decimal(str(b)) == 0:
        raise ValueError("Cannot divide by zero.")
    return Decimal(str(a)) / Decimal(str(b))


def calculate(expression: str):
    """
    Evaluate a simple arithmetic expression string.
    Format: <number> <operator> <number>
    Example: calculate("10 + 5") -> Decimal('15')
    """
    parts = expression.strip().split()
    if len(parts) != 3:
        raise ValueError(f"Invalid expression: '{expression}'. Use: <num> <op> <num>")
    left, op, right = parts
    try:
        l, r = Decimal(left), Decimal(right)
    except InvalidOperation:
        raise ValueError(f"Invalid numbers: {left}, {right}")
    ops = {"+": add, "-": subtract, "*": multiply, "/": divide}
    if op not in ops:
        raise ValueError(f"Unknown operator: {op}. Use +, -, *, /")
    return ops[op](l, r)


