"""
REST API
Auto-generated by NEXUS Coder AI
Requires: fastapi>=0.110.0, uvicorn>=0.29.0
"""

import json
import uuid
import hashlib
from datetime import datetime
from typing import Any

try:
    from fastapi import FastAPI, HTTPException, Header
    from fastapi.responses import JSONResponse
    from pydantic import BaseModel
    import uvicorn
    FASTAPI_AVAILABLE = True
except ImportError:
    FASTAPI_AVAILABLE = False
    FastAPI = None

app = FastAPI(
    title="NEXUS REST API",
    version="1.0.0",
    description="Auto-generated by NEXUS Coder AI",
) if FASTAPI_AVAILABLE else None

# ── In-memory data store ────────────────────────────────────────── #
_resources: dict = {}


def generate_id() -> str:
    """Generate a short unique ID."""
    return str(uuid.uuid4())[:8]


def get_timestamp() -> str:
    """Return current UTC timestamp."""
    return datetime.utcnow().isoformat()


def build_response(data: Any, success: bool = True) -> dict:
    """Build a standardised API response envelope."""
    return {
        "success":   success,
        "data":      data,
        "timestamp": get_timestamp(),
    }


def validate_resource(data: dict) -> list:
    """Return list of validation errors."""
    errors = []
    if not data.get("name", "").strip():
        errors.append("name is required and cannot be empty")
    return errors


if FASTAPI_AVAILABLE:

    class ResourceIn(BaseModel):
        name: str
        data: dict = {}

    @app.get("/health")
    def health_check():
        return build_response({"status": "healthy", "resources": len(_resources)})

    @app.get("/api/v1/resources")
    def list_resources(limit: int = 50, offset: int = 0):
        items  = list(_resources.values())
        paged  = items[offset: offset + limit]
        return build_response({
            "items":  paged,
            "total":  len(items),
            "limit":  limit,
            "offset": offset,
        })

    @app.post("/api/v1/resources", status_code=201)
    def create_resource(body: ResourceIn):
        resource = {
            "id":         generate_id(),
            "name":       body.name,
            "data":       body.data,
            "created_at": get_timestamp(),
            "updated_at": get_timestamp(),
        }
        _resources[resource["id"]] = resource
        return build_response(resource)

    @app.get("/api/v1/resources/{resource_id}")
    def get_resource(resource_id: str):
        resource = _resources.get(resource_id)
        if not resource:
            raise HTTPException(status_code=404, detail="Resource not found")
        return build_response(resource)

    @app.put("/api/v1/resources/{resource_id}")
    def update_resource(resource_id: str, body: ResourceIn):
        if resource_id not in _resources:
            raise HTTPException(status_code=404, detail="Resource not found")
        _resources[resource_id].update({
            "name":       body.name,
            "data":       body.data,
            "updated_at": get_timestamp(),
        })
        return build_response(_resources[resource_id])

    @app.delete("/api/v1/resources/{resource_id}")
    def delete_resource(resource_id: str):
        if resource_id not in _resources:
            raise HTTPException(status_code=404, detail="Resource not found")
        del _resources[resource_id]
        return build_response({"deleted": resource_id})


def start_server(host: str = "0.0.0.0", port: int = 8000):
    """Start the API server."""
    if not FASTAPI_AVAILABLE:
        print("FastAPI not installed. Run: pip install fastapi uvicorn")
        return
    uvicorn.run(app, host=host, port=port)


if __name__ == "__main__":
    start_server()
